def quote_value(text):
    """
    The new quote block's value for a plain-text quote: rich text with one
    paragraph per line, and a last line that starts with a dash moved into
    the attribution
    """
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    attribution = ""
    if len(lines) > 1 and lines[-1][0] in "—–-":
        attribution = lines.pop().lstrip("—–- ")
    return {
        "text": "".join(f"<p>{escape(line)}</p>" for line in lines),
        "attribution": attribution,
    }


def convert_quotes(stream_data):
    """Convert the plain-text quotes in a body's raw data; return whether any were"""
    changed = False
    for child in stream_data or []:
        if child.get("type") == "quote" and isinstance(child.get("value"), str):
            child["value"] = quote_value(child["value"])
            changed = True
    return changed


def convert_toc_accordions(stream_data):
    """
    Replace hand-made "Table of Contents" accordions with the new table of
    contents block; return whether any were
    """
    changed = False
    for child in stream_data or []:
        if (
            child.get("type") == "accordion"
            and child["value"].get("title", "").strip().lower() == "table of contents"
        ):
            child["type"] = "table_of_contents"
            child["value"] = {
                "title": child["value"]["title"].strip(),
                "depth": "3",
                "collapsible": True,
                "style": "simple",
                "size": "normal",
                "numbered": False,
                "bold_main_headings": True,
            }
            changed = True
    return changed


def update_bodies(apps, convert, all_revisions):
    """
    Apply convert to the raw body data of each page and home introduction,
    and to their revisions: all of them, or only each page's latest and live
    revision (enough for the editor to open, and republish, the change)
    """
    current_revision_ids = set()
    for model_name in ["aboutpage", "homeintroduction", "sitepage"]:
        model = apps.get_model("pages", model_name)
        for instance in model.objects.annotate(raw_body=Cast("body", JSONField())):
            if convert(instance.raw_body):
                instance.body = instance.raw_body
                instance.save(update_fields=["body"])
            current_revision_ids.update(
                getattr(instance, field, None)
                for field in ["latest_revision_id", "live_revision_id"]
            )

    ContentType = apps.get_model("contenttypes", "ContentType")
    Revision = apps.get_model("wagtailcore", "Revision")
    content_types = ContentType.objects.filter(app_label="pages", model__in=MODELS)
    revisions = Revision.objects.filter(content_type__in=content_types)
    if not all_revisions:
        revisions = revisions.filter(id__in=current_revision_ids - {None})
    for revision in revisions:
        body = revision.content.get("body")
        if not body:
            continue
        try:
            stream_data = json.loads(body) if isinstance(body, str) else body
        except json.JSONDecodeError:
            # From before the body was a StreamField, so it has no blocks
            continue
        if convert(stream_data):
            revision.content["body"] = (
                json.dumps(stream_data) if isinstance(body, str) else stream_data
            )
            revision.save(update_fields=["content"])


def migrate_bodies(apps, schema_editor):
    # Every revision, since the old plain-text quotes can't be opened as the
    # new quote block
    update_bodies(apps, convert_quotes, all_revisions=True)
    update_bodies(apps, convert_toc_accordions, all_revisions=False)


